import { test, expect } from '@playwright/test';

test.describe('Async Data Fetching - Non-Blocking Initial Render', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should render initial page content while async data is loading in the background', async ({ page }) => {
    // Verify initial page content is visible before async data loads
    const welcomeMessage = page.getByRole('heading', { name: /welcome/i });
    await expect(welcomeMessage).toBeVisible();

    const pageTitle = page.getByRole('heading', { name: /dashboard/i });
    await expect(pageTitle).toBeVisible();

    // Verify loading indicator is displayed for async data
    const loadingSpinner = page.getByTestId('loading-spinner');
    await expect(loadingSpinner).toBeVisible();

    // Verify initial data placeholder is visible
    const dataPlaceholder = page.getByTestId('data-placeholder');
    await expect(dataPlaceholder).toBeVisible();

    // Wait for async data to load
    await page.waitForTimeout(1000);

    // Verify loading indicator is no longer visible
    await expect(loadingSpinner).not.toBeVisible();

    // Verify async data is now displayed
    const asyncData = page.getByTestId('async-data');
    await expect(asyncData).toBeVisible();
    await expect(asyncData).toContainText('Data loaded successfully');

    // Verify page is fully interactive
    const refreshButton = page.getByRole('button', { name: /refresh/i });
    await expect(refreshButton).toBeEnabled();
  });

  test('should handle async data loading errors gracefully without blocking page render', async ({ page }) => {
    // Intercept the async data API call and simulate an error
    await page.route('**/api/data', route => {
      route.abort('failed');
    });

    // Verify initial page content is visible
    const welcomeMessage = page.getByRole('heading', { name: /welcome/i });
    await expect(welcomeMessage).toBeVisible();

    // Verify loading indicator is displayed
    const loadingSpinner = page.getByTestId('loading-spinner');
    await expect(loadingSpinner).toBeVisible();

    // Wait for async data to fail
    await page.waitForTimeout(1000);

    // Verify loading indicator is no longer visible
    await expect(loadingSpinner).not.toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByTestId('error-message');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Failed to load data');

    // Verify page content is still visible and interactive
    const pageTitle = page.getByRole('heading', { name: /dashboard/i });
    await expect(pageTitle).toBeVisible();

    const refreshButton = page.getByRole('button', { name: /refresh/i });
    await expect(refreshButton).toBeEnabled();

    // Verify user can interact with non-async elements
    const settingsLink = page.getByRole('link', { name: /settings/i });
    await expect(settingsLink).toBeVisible();
  });
});
